<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/attendance.php';
$current=tuman_require_role('TEACHER');$db=tuman_database();$error=null;$students=array_filter(tuman_teacher_students($db,$current['id']),fn($s)=>$s['assignment_status']==='ACTIVE');$rules=array_filter(tuman_teacher_billing_rules($db,$current['id']),fn($r)=>$r['status']==='ACTIVE'&&$r['billing_mode']==='HOURLY');$v=['assignment_id'=>'','session_date'=>gmdate('Y-m-d'),'status'=>'PRESENT','start_time'=>'','end_time'=>'','billing_rule_id'=>'','remarks'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$assignment=filter_var($v['assignment_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment)throw new InvalidArgumentException('Choose a student.');tuman_create_attendance($db,$current['id'],(int)$assignment,$v);header('Location: /Tuman/teacher/attendance.php?created=1');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to save attendance right now.';}}tuman_teacher_page_start('Record attendance');
?>
<h1>Record attendance</h1><p>Select an hourly rule only when that session has an additional hourly charge. If no monthly rule exists, Tuman uses the highest applicable hourly rate when no rule is selected.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select id="assignment_id" name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=(int)$s['assignment_id']?>"<?=$v['assignment_id']==$s['assignment_id']?' selected':''?>><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Session date <input id="session_date" type="date" name="session_date" required value="<?=htmlspecialchars($v['session_date'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Status <select name="status"><?php foreach(TUMAN_ATTENDANCE_STATUSES as $s):?><option value="<?=$s?>"<?=$s===$v['status']?' selected':''?>><?=$s?></option><?php endforeach;?></select></label></p><p><label>Start time <input type="time" name="start_time" value="<?=htmlspecialchars($v['start_time'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>End time <input type="time" name="end_time" value="<?=htmlspecialchars($v['end_time'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Hourly rule <select id="billing_rule_id" name="billing_rule_id"><option value="">Automatic / no extra hourly charge</option><?php foreach($rules as $r):?><option value="<?=(int)$r['id']?>" data-assignment="<?=(int)$r['teacher_student_id']?>" data-from="<?=htmlspecialchars($r['effective_from'],ENT_QUOTES,'UTF-8')?>" data-to="<?=htmlspecialchars($r['effective_to']??'',ENT_QUOTES,'UTF-8')?>"<?=$v['billing_rule_id']==$r['id']?' selected':''?>><?=htmlspecialchars(($r['rule_name']??('Rule #'.$r['id'])).' — '.tuman_billing_rate_label($r['rate'],'HOURLY',$r['currency_code']),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Remarks <textarea name="remarks"><?=htmlspecialchars($v['remarks'],ENT_QUOTES,'UTF-8')?></textarea></label></p><p><button>Save attendance</button> <a href="/Tuman/teacher/attendance.php">Cancel</a></p></form><script>const student=document.getElementById('assignment_id'),date=document.getElementById('session_date'),rules=document.getElementById('billing_rule_id');function filterRules(){for(const option of rules.options){if(!option.value)continue;const matches=option.dataset.assignment===student.value&&(!date.value||(option.dataset.from<=date.value&&(!option.dataset.to||option.dataset.to>=date.value)));option.hidden=!matches;option.disabled=!matches;if(!matches&&option.selected)rules.value='';}}student.addEventListener('change',filterRules);date.addEventListener('change',filterRules);filterRules();</script>
<?php tuman_teacher_page_end();?>
